// Astro the mascot: pose images (embedded, so this one file is all you upload), avatar, popup bubble and idle nudges.
// Pure addition. Replaces the old face-icon avatar. Loaded after persona.js and before economy.js / astro-chat.js.
const ASTRO_ART={"avatar": "data:image/webp;base64,", "hello": "data:image/webp;base64,", "letsgo": "data:image/webp;base64,", "cheer": "data:image/webp;base64,", "celebrate": "data:image/webp;base64,", "fire": "data:image/webp;base64,", "sad": "data:image/webp;base64,", "confused": "data:image/webp;base64,", "shy": "data:image/webp;base64,", "sceptic": "data:image/webp;base64,", "sleep": "data:image/webp;base64,", "coach": "data:image/webp;base64,", "guide": "data:image/webp;base64,", "music": "data:image/webp;base64,", "torch": "data:image/webp;base64,", "tangled": "data:image/webp;base64,", "thumbs": "data:image/webp;base64,", "wave": "data:image/webp;base64,", "think": "data:image/webp;base64,", "talk": "data:image/webp;base64,", "bigcheer": "data:image/webp;base64,", "logo": "data:image/webp;base64,"};
// moods -> image. Unknown moods fall back to "hello".
const ASTRO_MOOD={hello:"hello",start:"letsgo",right:"cheer",win:"celebrate",streak:"fire",wrong:"confused",fail:"sad",cheer:"shy",idle:"sceptic",sleep:"sleep",tip:"coach",guide:"guide",listen:"music",work:"torch",lost:"tangled",think:"think",talk:"talk",thumbs:"thumbs",wave:"wave"};
function astroPose(m,px){const k=ASTRO_MOOD[m]||m||"hello",s=ASTRO_ART[k]||ASTRO_ART.hello;px=px||72;return `<img class="apose" src="${s}" alt="Astro" width="${px}" style="width:${px}px;height:auto;max-width:100%;flex:none;vertical-align:middle">`}
// avatar (round badge) used by the chat, the floating button and small labels
function astroAv(px){px=px||36;return `<img class="aav" src="${ASTRO_ART.avatar}" alt="Astro" width="${px}" height="${px}" style="width:${px}px;height:${px}px;border-radius:50%;flex:none;vertical-align:middle;object-fit:cover">`}
(function(){
 const st=document.createElement("style");st.textContent=`.afab img{display:block;width:100%;height:100%;border-radius:50%}#asay{position:fixed;left:10px;right:70px;bottom:92px;max-width:430px;z-index:900;display:flex;gap:10px;align-items:flex-end;background:var(--card,#1c1c1e);color:var(--fg,#fff);border:1px solid var(--bd,#333);border-radius:16px;padding:10px 12px 10px 8px;box-shadow:0 8px 28px rgba(0,0,0,.4);animation:asin .25s ease-out}#asay .at{flex:1;font-size:15px;line-height:1.45}#asay .ax{background:none;border:0;color:inherit;opacity:.6;font-size:20px;line-height:1;padding:0 4px;width:auto;cursor:pointer}@keyframes asin{from{transform:translateY(14px);opacity:0}to{transform:none;opacity:1}}@media(prefers-reduced-motion:reduce){#asay{animation:none}}`;document.head.appendChild(st);
 try{const l=document.querySelector('link[rel~="icon"]');if(l){l.type="image/webp";l.href=ASTRO_ART.avatar}}catch(e){}
 let hideT=null,lastAt=0,idleAt=Date.now();
 // popup bubble: astroSay(message html, [buttonLabel, fn], force, mood)
 window.astroSay=function(msg,act,force,mood){
  try{if(typeof ST!=="undefined"&&ST.aoff&&!force)return}catch(e){}
  if(!force&&Date.now()-lastAt<9e4)return;lastAt=Date.now();
  let b=document.getElementById("asay");if(!b){b=document.createElement("div");b.id="asay";b.setAttribute("role","status");document.body.appendChild(b)}
  b.innerHTML=`${astroPose(mood||"hello",74)}<div class="at"><b>Astro</b><br>${msg}${act?`<div style="margin-top:8px"><button type="button" class="btn p" data-asay="go" style="padding:6px 12px;width:auto">${act[0]}</button></div>`:""}</div><button type="button" class="ax" data-asay="x" aria-label="Close">×</button>`;
  b._a=act;clearTimeout(hideT);hideT=setTimeout(()=>{const e=document.getElementById("asay");if(e)e.remove()},13000)};
 document.addEventListener("click",e=>{const t=e.target.closest("[data-asay]");if(!t)return;const b=document.getElementById("asay");if(t.dataset.asay=="go"&&b&&b._a){try{b._a[1]()}catch(x){}}if(b)b.remove()});
 ["pointerdown","keydown","scroll","touchstart"].forEach(ev=>document.addEventListener(ev,()=>idleAt=Date.now(),{passive:true}));
 // gentle idle nudges: first a raised eyebrow, then he falls asleep. Never while a popup or sheet is open, never more than every 5 minutes.
 setInterval(()=>{try{if(document.visibilityState!=="visible"||ST.aoff)return;const idle=Date.now()-idleAt;if(idle<12e4||Date.now()-lastAt<3e5)return;if(document.getElementById("asay")||document.getElementById("sheet")&&document.getElementById("sheet").classList.contains("on"))return;
  const line=typeof ABrain!=="undefined"&&ABrain.idle?ABrain.idle():"Are we learning or what?";
  astroSay(line,["Let’s go",()=>{const b=[...document.querySelectorAll("#bbar button")].find(x=>/Learn/.test(x.textContent));if(b)b.click()}],false,idle>3e5?"sleep":"idle");idleAt=Date.now()}catch(e){}},15000);
})();
